    map['id'] = Variable<String>(id);
    map['folder_id'] = Variable<String>(folderId);
    map['user_id'] = Variable<String>(userId);
    map['title'] = Variable<String>(title);
    map['updated_at'] = Variable<int>(updatedAt);
    map['version'] = Variable<int>(version);
    map['deleted'] = Variable<int>(deleted);
    if (!nullToAbsent || trashedAt != null) {
      map['trashed_at'] = Variable<int>(trashedAt);
    }
    map['created_at'] = Variable<int>(createdAt);
    if (!nullToAbsent || preacherId != null) {
      map['preacher_id'] = Variable<String>(preacherId);
    }
    if (!nullToAbsent || noteDate != null) {
      map['note_date'] = Variable<int>(noteDate);
    }
    map['field_updated_at'] = Variable<String>(fieldUpdatedAt);
    if (!nullToAbsent || documentJson != null) {
      map['document_json'] = Variable<String>(documentJson);
    }
    return map;
  }

