    map['device_id'] = Variable<String>(deviceId);
    map['synced'] = Variable<int>(synced);
    map['entity_version'] = Variable<int>(entityVersion);
    if (!nullToAbsent || serverTimestamp != null) {
      map['server_timestamp'] = Variable<int>(serverTimestamp);
    }
    if (!nullToAbsent || failedAt != null) {
      map['failed_at'] = Variable<int>(failedAt);
