class Song extends DataClass implements Insertable<Song> {
  /// Primary key - stable UUID (never changes)
  final String id;

  /// Owner user ID
  final String userId;

  /// Song title (mandatory)
  final String title;

  /// Folder ID for organization (references Folders table)
  final String? folderId;

  /// Clean lyrics content (plain text with line breaks)
  final String lyrics;

  /// Lyrics with inline chord annotations
  final String chords;

  /// Primary language of the song
  final String language;

  /// Optional songbook/collection identifier
  final String? book;

  /// Preview text (auto-generated from lyrics, first ~50 chars)
  final String preview;

  /// User-defined tags (comma-separated)
  final String tags;

  /// Musical scale/key (e.g. "C", "Dm", "F#", "Bb")
  final String scale;

  /// Free-form notes or references related to the song
  /// (e.g. author, source URL, performance notes)
  final String notes;

  /// Structured chord lines as JSON array, stored separately from lyrics.
  /// Each entry: {"lineIndex": int, "rawChords": "G D Em C"}
  /// lineIndex maps to the corresponding lyric line.
  final String chordLines;

  /// Whether song has chord annotations
  final int hasChords;

  /// Favorite flag
  final int isFavorite;

  /// Last update timestamp (Unix milliseconds)
  final int updatedAt;

  /// Version number for optimistic locking
  final int version;

  /// Soft delete flag (0 = active, 1 = deleted)
  final int deleted;

  /// Timestamp when moved to trash (Unix milliseconds, null = not trashed)
  final int? trashedAt;

  /// Creation timestamp (Unix milliseconds)
  final int createdAt;
  const Song({
    required this.id,
    required this.userId,
    required this.title,
    this.folderId,
    required this.lyrics,
    required this.chords,
    required this.language,
    this.book,
    required this.preview,
    required this.tags,
    required this.scale,
    required this.notes,
    required this.chordLines,
    required this.hasChords,
    required this.isFavorite,
    required this.updatedAt,
    required this.version,
    required this.deleted,
    this.trashedAt,
    required this.createdAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['user_id'] = Variable<String>(userId);
    map['title'] = Variable<String>(title);
    if (!nullToAbsent || folderId != null) {
      map['folder_id'] = Variable<String>(folderId);
    }
    map['lyrics'] = Variable<String>(lyrics);
    map['chords'] = Variable<String>(chords);
    map['language'] = Variable<String>(language);
    if (!nullToAbsent || book != null) {
      map['book'] = Variable<String>(book);
    }
    map['preview'] = Variable<String>(preview);
    map['tags'] = Variable<String>(tags);
    map['scale'] = Variable<String>(scale);
    map['notes'] = Variable<String>(notes);
    map['chord_lines'] = Variable<String>(chordLines);
    map['has_chords'] = Variable<int>(hasChords);
    map['is_favorite'] = Variable<int>(isFavorite);
    map['updated_at'] = Variable<int>(updatedAt);
    map['version'] = Variable<int>(version);
    map['deleted'] = Variable<int>(deleted);
    if (!nullToAbsent || trashedAt != null) {
      map['trashed_at'] = Variable<int>(trashedAt);
    }
    map['created_at'] = Variable<int>(createdAt);
    return map;
  }

  SongsCompanion toCompanion(bool nullToAbsent) {
    return SongsCompanion(
      id: Value(id),
      userId: Value(userId),
      title: Value(title),
      folderId: folderId == null && nullToAbsent
          ? const Value.absent()
          : Value(folderId),
      lyrics: Value(lyrics),
      chords: Value(chords),
      language: Value(language),
      book: book == null && nullToAbsent ? const Value.absent() : Value(book),
      preview: Value(preview),
      tags: Value(tags),
      scale: Value(scale),
      notes: Value(notes),
      chordLines: Value(chordLines),
      hasChords: Value(hasChords),
      isFavorite: Value(isFavorite),
      updatedAt: Value(updatedAt),
      version: Value(version),
      deleted: Value(deleted),
      trashedAt: trashedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(trashedAt),
      createdAt: Value(createdAt),
    );
  }

  factory Song.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Song(
      id: serializer.fromJson<String>(json['id']),
      userId: serializer.fromJson<String>(json['userId']),
      title: serializer.fromJson<String>(json['title']),
      folderId: serializer.fromJson<String?>(json['folderId']),
      lyrics: serializer.fromJson<String>(json['lyrics']),
      chords: serializer.fromJson<String>(json['chords']),
      language: serializer.fromJson<String>(json['language']),
      book: serializer.fromJson<String?>(json['book']),
