class PromiseCondition extends DataClass
    implements Insertable<PromiseCondition> {
  /// Primary key - stable UUID
  final String id;

  /// Foreign key to promises table
  final String promiseId;

  /// Owner user ID
  final String userId;

  /// Condition description text
  final String description;

  /// Optional notes about this condition
  final String notes;

  /// Status: ACTIVE, MET, NOT_MET
  final String status;

  /// Last update timestamp (Unix milliseconds)
  final int updatedAt;

  /// Version number for optimistic locking
  final int version;

  /// Soft delete flag (0 = active, 1 = deleted)
  final int deleted;

  /// Timestamp when moved to trash (Unix milliseconds, null = not trashed)
  final int? trashedAt;

  /// Creation timestamp (Unix milliseconds)
  final int createdAt;
  const PromiseCondition({
    required this.id,
    required this.promiseId,
    required this.userId,
    required this.description,
    required this.notes,
