class BibleVersionState extends DataClass
    implements Insertable<BibleVersionState> {
  /// Translation code, e.g. 'NKJV'. Also the primary key.
  final String code;

  /// Full display name, e.g. 'New King James Version'.
  final String name;

  /// S3 URL for the per-translation SQLite database file.
  final String downloadUrl;

  /// Approximate download size in MB (for UI display only).
  final int approximateSizeMb;

  /// Display order from the server (lower = shown first).
  final int sortOrder;

  /// Whether this is the user's active default translation.
  /// Exactly one row should be true at a time.
  final bool isDefault;

  /// Unix ms when this row was last refreshed from the server.
  final int? fetchedAt;
  const BibleVersionState({
    required this.code,
    required this.name,
    required this.downloadUrl,
    required this.approximateSizeMb,
    required this.sortOrder,
    required this.isDefault,
    this.fetchedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['code'] = Variable<String>(code);
    map['name'] = Variable<String>(name);
    map['download_url'] = Variable<String>(downloadUrl);
    map['approximate_size_mb'] = Variable<int>(approximateSizeMb);
    map['sort_order'] = Variable<int>(sortOrder);
    map['is_default'] = Variable<bool>(isDefault);
    if (!nullToAbsent || fetchedAt != null) {
      map['fetched_at'] = Variable<int>(fetchedAt);
    }
    return map;
  }

  BibleVersionStatesCompanion toCompanion(bool nullToAbsent) {
    return BibleVersionStatesCompanion(
      code: Value(code),
      name: Value(name),
      downloadUrl: Value(downloadUrl),
      approximateSizeMb: Value(approximateSizeMb),
      sortOrder: Value(sortOrder),
      isDefault: Value(isDefault),
      fetchedAt: fetchedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(fetchedAt),
    );
  }

  factory BibleVersionState.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return BibleVersionState(
      code: serializer.fromJson<String>(json['code']),
      name: serializer.fromJson<String>(json['name']),
      downloadUrl: serializer.fromJson<String>(json['downloadUrl']),
      approximateSizeMb: serializer.fromJson<int>(json['approximateSizeMb']),
      sortOrder: serializer.fromJson<int>(json['sortOrder']),
      isDefault: serializer.fromJson<bool>(json['isDefault']),
      fetchedAt: serializer.fromJson<int?>(json['fetchedAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'code': serializer.toJson<String>(code),
      'name': serializer.toJson<String>(name),
      'downloadUrl': serializer.toJson<String>(downloadUrl),
      'approximateSizeMb': serializer.toJson<int>(approximateSizeMb),
      'sortOrder': serializer.toJson<int>(sortOrder),
      'isDefault': serializer.toJson<bool>(isDefault),
      'fetchedAt': serializer.toJson<int?>(fetchedAt),
    };
  }

  BibleVersionState copyWith({
    String? code,
    String? name,
    String? downloadUrl,
    int? approximateSizeMb,
    int? sortOrder,
    bool? isDefault,
    Value<int?> fetchedAt = const Value.absent(),
  }) => BibleVersionState(
    code: code ?? this.code,
    name: name ?? this.name,
    downloadUrl: downloadUrl ?? this.downloadUrl,
    approximateSizeMb: approximateSizeMb ?? this.approximateSizeMb,
    sortOrder: sortOrder ?? this.sortOrder,
    isDefault: isDefault ?? this.isDefault,
    fetchedAt: fetchedAt.present ? fetchedAt.value : this.fetchedAt,
  );
  BibleVersionState copyWithCompanion(BibleVersionStatesCompanion data) {
    return BibleVersionState(
      code: data.code.present ? data.code.value : this.code,
      name: data.name.present ? data.name.value : this.name,
      downloadUrl: data.downloadUrl.present
          ? data.downloadUrl.value
          : this.downloadUrl,
      approximateSizeMb: data.approximateSizeMb.present
          ? data.approximateSizeMb.value
          : this.approximateSizeMb,
      sortOrder: data.sortOrder.present ? data.sortOrder.value : this.sortOrder,
      isDefault: data.isDefault.present ? data.isDefault.value : this.isDefault,
      fetchedAt: data.fetchedAt.present ? data.fetchedAt.value : this.fetchedAt,
    );
  }

  @override
  String toString() {
    return (StringBuffer('BibleVersionState(')
          ..write('code: $code, ')
          ..write('name: $name, ')
          ..write('downloadUrl: $downloadUrl, ')
          ..write('approximateSizeMb: $approximateSizeMb, ')
          ..write('sortOrder: $sortOrder, ')
          ..write('isDefault: $isDefault, ')
          ..write('fetchedAt: $fetchedAt')
          ..write(')'))
        .toString();
  }

